package com.thang.nihongo_user.controller;
import com.thang.nihongo_user.repository.*;import com.thang.nihongo_user.model.AdminCommerceAudit;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.transaction.annotation.Transactional;import org.springframework.data.domain.PageRequest;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/nihongo-user/admin/operations") @PreAuthorize("hasRole('ADMIN')") @RequiredArgsConstructor
public class LearningOperationsController {
 private final WalletOutboxRepository outbox;private final AdminCommerceAuditRepository audit;
 public record Job(String id,int attempts,Instant nextAttempt,boolean leased){}public record Retry(@NotBlank @Size(min=10,max=500) String reason){}
 @GetMapping public Map<String,Object> health(){return Map.of("service","nihongo-user-service","pending",outbox.countByPublishedAtIsNull(),"serverTime",System.currentTimeMillis());}
 @GetMapping("/queue") public Object queue(@RequestParam(defaultValue="0") int page){if(page<0)throw bad("Trang không hợp lệ");var result=outbox.findByPublishedAtIsNullOrderByCreatedAtAscIdAsc(PageRequest.of(page,20)).map(r->new Job(r.getId(),r.getAttempts(),r.getNextAttemptAt(),r.getClaimedUntil()!=null&&r.getClaimedUntil().isAfter(Instant.now())));return ClassroomController.PageView.from(result);}
 @PostMapping("/queue/{id}/retry") @Transactional public void retry(@AuthenticationPrincipal Jwt jwt,@PathVariable String id,@Valid @RequestBody Retry input){var row=outbox.lock(id).orElseThrow(()->bad("Không tìm thấy tác vụ"));if(row.getPublishedAt()!=null||row.getClaimedUntil()!=null&&row.getClaimedUntil().isAfter(Instant.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Tác vụ đã gửi hoặc đang xử lý");row.setNextAttemptAt(Instant.now());row.setClaimedUntil(null);var a=new AdminCommerceAudit();a.setActor(jwt.getSubject());a.setAction("WALLET_EVENT_RETRY");a.setTarget("event:"+id);a.setDetail(input.reason().trim());a.setCreatedAt(LocalDateTime.now());audit.save(a);}
 private static ResponseStatusException bad(String text){return new ResponseStatusException(HttpStatus.BAD_REQUEST,text);}
}
